const InfoProduct = memo(({ initialCount, counter, supplier, paramData }) => (
  <View style={styles.infoProductZone}>
    <View style={styles.detailsContainer}>
      <Text style={styles.compagny}>{supplier}</Text>
      <Text style={[styles.productName, { color: counter === initialCount ? 'blue' : styles.productName.color }]}>
        {paramData.name}</Text>
      <Text style={styles.productCode}>{paramData.code}</Text>
      <Text style={styles.productQuantityInStock}>Quantity in stock: {paramData.inStock}</Text>
      <View style={styles.box}>
        {[0, paramData.quantityPerBox, 0].map((boxQty, index) => (
          <View key={index} style={styles.oneBox}>
            <Text style={styles.boxes}>{boxQty}</Text>
            <Feather name="box" size={26} color="black" />
          </View>
        ))}
      </View>
    </View>
    <View style={styles.imageContainer}>
      <Image style={styles.productImage} source={require('../../assets/gamadim.png')} />
    </View>
  </View>
));

const Counter = memo(({ initialCount, counter, setCounter }) => {
  const maxLimit = initialCount;
  
  const handleQuantity = useCallback(() => {
    setCounter(initialCount);
  }, [initialCount, setCounter]);

  const handleChange = useCallback((number) => {
    const newValue = parseInt(number, 10);
    if (!isNaN(newValue) && newValue >= 0 && newValue <= maxLimit) {
      setCounter(newValue);
    } else {
      Alert.alert('Invalid input', `Enter a number between 0 and ${maxLimit}`);
    }
  }, [maxLimit, setCounter]);

  return (
    <>
      <TouchableOpacity style={styles.quantityBefore} onPress={handleQuantity}>
        <Text style={styles.before}>Initial Quantity: {initialCount}</Text>
      </TouchableOpacity>
      <View style={styles.counterZone}>
        <Pressable style={[styles.unitsButton, { backgroundColor: initialCount === counter ? 'blue' : styles.unitsButton.backgroundColor }]}>
          <Text style={styles.unitButtonText}>Units</Text>
        </Pressable>
        <View style={styles.counter}>
          <Pressable onPress={() => setCounter(Math.max(0, counter - 1))} style={[styles.counterButton]}>
            <Feather name="minus" size={60} color={initialCount === counter ? 'blue' : counter === 0 ? '#f2f2f2' : 'red'} />
          </Pressable>
          <TextInput  style={[styles.TextCounter, { color: initialCount === counter ? 'blue' : styles.TextCounter.color }]} value={String(counter)} keyboardType="numeric" onChangeText={handleChange} />
          <Pressable onPress={() => setCounter(Math.min(maxLimit, counter + 1))} style={[styles.counterButton]}>
            <Feather name="plus" size={60} color={initialCount === counter ? '#f2f2f2' : 'red'} />
          </Pressable>
        </View>
        {initialCount !== counter && <OpenModalButtonApproval />}
      </View>
    </>
  );
});

const ApproveButtons = ({ navigation, handleUpdateStatus, isOpen, setIsOpen, counter, initialQuantity, paramData, supplier, orderId, productId }) => (
  <View style={styles.approve}>
    <Pressable onPress={() => { setIsOpen(false); handleUpdateStatus(); }} style={styles.nextButton}>
      <Text style={styles.approveButtonText}>Next</Text>
    </Pressable>
    <Pressable onPress={() => navigation.goBack()} style={styles.cancelButton}>
      <Text style={styles.approveButtonText}>Cancel</Text>
    </Pressable>
  </View>
);

export const EdiItemApprovalScreen = ({ navigation }) => {
  const route = useRoute();
  const { paramData, initialQuantity, supplier, orderId } = route.params || {};
  const [isModalOpen, setModalOpen] = useState(true);
  const [counter, setCounter] = useState(0);

  const [updateOrderProductStatus] = useMutation(UPDATE_ORDER_PRODUCT_STATUS_MUTATION);
  const handleUpdateStatus = useCallback(async () => {
    try {
      await updateOrderProductStatus({ variables: { orderId, finalQuantity: counter, productId: paramData.id, isOpen: false } });
    } catch (err) {
      console.error('Error updating orderProduct status:', err);
    }
  }, [updateOrderProductStatus, counter, orderId, paramData.id]);

  return (
    <View style={styles.modalContainer}>
      {isModalOpen && (
        <Modal animationType="fade" transparent={true} visible={isModalOpen}>
          <InfoProduct initialCount={initialQuantity} counter={counter} supplier={supplier} paramData={paramData} />
          <Counter initialCount={initialQuantity} counter={counter} setCounter={setCounter} />
          <ApproveButtons navigation={navigation} handleUpdateStatus={handleUpdateStatus} isOpen={isModalOpen} setIsOpen={setModalOpen} counter={counter} initialQuantity={initialQuantity} paramData={paramData} supplier={supplier} orderId={orderId} productId={paramData.id} />
        </Modal>
      )}
    </View>
  );
};






